-- P_V26_QUERY (probes V26-TABLE-PLAIN, V26-CTE-BACKWARD, V26-CTE-FORWARD,
--     V26-CTE-FORWARD-PLAIN, V26-RECURSIVE-COLUMNS, V26-RECURSIVE-NO-COLUMNS)
-- SET OPTION COMMIT = *NONE, CLOSQLCSR = *ENDMOD
-- | BEGIN
-- |   DECLARE V_SQL VARCHAR(4000);
-- |   DECLARE V_OLD VARCHAR(128);
-- |   DECLARE V_EOF INTEGER DEFAULT 0;
-- |   DECLARE V_N INTEGER DEFAULT 0;
-- |   DECLARE X INTEGER;
-- |   DECLARE C1 CURSOR FOR S1;
-- |   SET O_STATE = '00000';
-- |   SET O_CODE = 0;
-- |   SET V_OLD = CURRENT SCHEMA;
-- |   BEGIN
-- |     DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET V_N = 0;
-- |     SET V_SQL = 'CREATE TABLE SQLDFPROBE.CTEB (X INTEGER)';
-- |     EXECUTE IMMEDIATE V_SQL;
-- |   END;
-- |   BEGIN
-- |     DECLARE EXIT HANDLER FOR SQLEXCEPTION
-- |       GET DIAGNOSTICS CONDITION 1 O_STATE = RETURNED_SQLSTATE,
-- |         O_CODE = DB2_RETURNED_SQLCODE;
-- |     DECLARE CONTINUE HANDLER FOR NOT FOUND SET V_EOF = 1;
-- |     SET V_SQL = 'DELETE FROM SQLDFPROBE.CTEB';
-- |     EXECUTE IMMEDIATE V_SQL;
-- |     SET V_SQL = 'INSERT INTO SQLDFPROBE.CTEB (X) VALUES (7)';
-- |     EXECUTE IMMEDIATE V_SQL;
-- |     SET SCHEMA SQLDFPROBE;
-- |     PREPARE S1 FROM Q;
-- |     OPEN C1;
-- |     FETCH C1 INTO X;
-- |     WHILE V_EOF = 0 AND V_N < 1000 DO
-- |       SET V_N = V_N + 1;
-- |       IF V_N = 1 THEN SET O_N1 = X; END IF;
-- |       FETCH C1 INTO X;
-- |     END WHILE;
-- |     CLOSE C1;
-- |     SET O_N2 = V_N;
-- |   END;
-- |   SET SCHEMA = V_OLD;
-- | END
BEGIN
  DECLARE V_SQL VARCHAR(16000);
  DECLARE V_STATE CHAR(5) DEFAULT '00000';
  DECLARE V_CODE INTEGER DEFAULT 0;
  DECLARE V_MSG VARCHAR(2000) DEFAULT '';
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    GET DIAGNOSTICS CONDITION 1 V_STATE = RETURNED_SQLSTATE,
      V_CODE = DB2_RETURNED_SQLCODE, V_MSG = MESSAGE_TEXT;
  SET V_SQL =
       'CREATE OR REPLACE PROCEDURE SQLDFPROBE.P_V26_QUERY (IN Q '
    || 'VARCHAR(4000), OUT O_STATE CHAR(5), OUT O_CODE INTEGER, OUT O_N1 '
    || 'INTEGER, OUT O_N2 INTEGER, OUT O_TEXT VARCHAR(200)) LANGUAGE SQL '
    || 'MODIFIES SQL DATA SET OPTION COMMIT = *NONE, CLOSQLCSR = *ENDMOD '
    || 'BEGIN DECLARE V_SQL VARCHAR(4000); DECLARE V_OLD VARCHAR(128); '
    || 'DECLARE V_EOF INTEGER DEFAULT 0; DECLARE V_N INTEGER DEFAULT 0; '
    || 'DECLARE X INTEGER; DECLARE C1 CURSOR FOR S1; SET O_STATE = ''00000''; '
    || 'SET O_CODE = 0; SET V_OLD = CURRENT SCHEMA; BEGIN DECLARE CONTINUE '
    || 'HANDLER FOR SQLEXCEPTION SET V_N = 0; SET V_SQL = ''CREATE TABLE '
    || 'SQLDFPROBE.CTEB (X INTEGER)''; EXECUTE IMMEDIATE V_SQL; END; BEGIN '
    || 'DECLARE EXIT HANDLER FOR SQLEXCEPTION GET DIAGNOSTICS CONDITION 1 '
    || 'O_STATE = RETURNED_SQLSTATE, O_CODE = DB2_RETURNED_SQLCODE; DECLARE '
    || 'CONTINUE HANDLER FOR NOT FOUND SET V_EOF = 1; SET V_SQL = ''DELETE '
    || 'FROM SQLDFPROBE.CTEB''; EXECUTE IMMEDIATE V_SQL; SET V_SQL = ''INSERT '
    || 'INTO SQLDFPROBE.CTEB (X) VALUES (7)''; EXECUTE IMMEDIATE V_SQL; SET '
    || 'SCHEMA SQLDFPROBE; PREPARE S1 FROM Q; OPEN C1; FETCH C1 INTO X; WHILE '
    || 'V_EOF = 0 AND V_N < 1000 DO SET V_N = V_N + 1; IF V_N = 1 THEN SET '
    || 'O_N1 = X; END IF; FETCH C1 INTO X; END WHILE; CLOSE C1; SET O_N2 = '
    || 'V_N; END; SET SCHEMA = V_OLD; END';
  CALL SQLDFPROBE.RUN_DDL('PROC:V26_QUERY',
    'DROP PROCEDURE SQLDFPROBE.P_V26_QUERY', V_SQL);
  IF V_STATE <> '00000' THEN
    INSERT INTO SQLDFPROBE.RESULTS (R_PROBE, R_STEP, R_STATE, R_CODE, R_MSG)
      VALUES ('PROC:V26_QUERY', 'create', V_STATE, V_CODE,
        'CALL RUN_DDL failed: ' || V_MSG) WITH NC;
  END IF;
END;

