-- |   BEGIN
-- |     DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET V_OK = 'N';
-- |     EXECUTE IMMEDIATE 'DROP TABLE SQLDFPROBE.UX';
-- |     EXECUTE IMMEDIATE 'DROP SEQUENCE SQLDFPROBE.SQ';
-- |   END;
-- |   WHILE V_I < 6 DO
-- |     SET V_I = V_I + 1;
-- |     SET V_Q = CASE V_I WHEN 1 THEN P1 WHEN 2 THEN P2 WHEN 3 THEN P3
-- |       WHEN 4 THEN P4 WHEN 5 THEN P5 ELSE P6 END;
-- |     IF V_Q = '' THEN
-- |       SET O_TEXT = O_TEXT || '-';
-- |     ELSE
-- |       SET V_OK = 'Y';
-- |       BEGIN
-- |         DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
-- |           BEGIN
-- |             SET V_OK = 'N';
-- |             IF O_STATE = '00000' THEN
-- |               GET DIAGNOSTICS CONDITION 1 O_STATE = RETURNED_SQLSTATE,
-- |                 O_CODE = DB2_RETURNED_SQLCODE;
-- |             END IF;
-- |           END;
-- |         EXECUTE IMMEDIATE V_Q;
-- |       END;
-- |       SET O_TEXT = O_TEXT || V_OK;
-- |     END IF;
-- |   END WHILE;
-- |   BEGIN
-- |     DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET O_N1 = -1;
-- |     SELECT COUNT(*), MIN(K) INTO O_N1, O_N2 FROM SQLDFPROBE.UX;
-- |   END;
-- | END
