       'CREATE OR REPLACE PROCEDURE SQLDFPROBE.P_V29_DDL (IN P1 '
    || 'VARCHAR(1000), IN P2 VARCHAR(1000), IN P3 VARCHAR(1000), IN P4 '
    || 'VARCHAR(1000), IN P5 VARCHAR(1000), IN P6 VARCHAR(1000), OUT O_STATE '
    || 'CHAR(5), OUT O_CODE INTEGER, OUT O_N1 INTEGER, OUT O_N2 INTEGER, OUT '
    || 'O_TEXT VARCHAR(200)) LANGUAGE SQL MODIFIES SQL DATA SET OPTION COMMIT '
    || '= *NONE BEGIN DECLARE V_I INTEGER DEFAULT 0; DECLARE V_Q '
    || 'VARCHAR(1000); DECLARE V_OK CHAR(1); SET O_STATE = ''00000''; SET '
    || 'O_CODE = 0; SET O_TEXT = ''''; SET O_N1 = -1; BEGIN DECLARE CONTINUE '
    || 'HANDLER FOR SQLEXCEPTION SET V_OK = ''N''; EXECUTE IMMEDIATE ''DROP '
    || 'TABLE SQLDFPROBE.UX''; EXECUTE IMMEDIATE ''DROP SEQUENCE '
    || 'SQLDFPROBE.SQ''; END; WHILE V_I < 6 DO SET V_I = V_I + 1; SET V_Q = '
    || 'CASE V_I WHEN 1 THEN P1 WHEN 2 THEN P2 WHEN 3 THEN P3 WHEN 4 THEN P4 '
    || 'WHEN 5 THEN P5 ELSE P6 END; IF V_Q = '''' THEN SET O_TEXT = O_TEXT || '
    || '''-''; ELSE SET V_OK = ''Y''; BEGIN DECLARE CONTINUE HANDLER FOR '
    || 'SQLEXCEPTION BEGIN SET V_OK = ''N''; IF O_STATE = ''00000'' THEN GET '
    || 'DIAGNOSTICS CONDITION 1 O_STATE = RETURNED_SQLSTATE, O_CODE = '
    || 'DB2_RETURNED_SQLCODE; END IF; END; EXECUTE IMMEDIATE V_Q; END; SET '
    || 'O_TEXT = O_TEXT || V_OK; END IF; END WHILE; BEGIN DECLARE CONTINUE '
    || 'HANDLER FOR SQLEXCEPTION SET O_N1 = -1; SELECT COUNT(*), MIN(K) INTO '
    || 'O_N1, O_N2 FROM SQLDFPROBE.UX; END; END';
