-- |     SET O_TEXT = O_TEXT || '>' || COALESCE(V_B, 'null') || '|'
-- |       || COALESCE(TRIM(CHAR(V_C)), 'null');
-- |   END;
-- | END
BEGIN
  DECLARE V_SQL VARCHAR(16000);
  DECLARE V_STATE CHAR(5) DEFAULT '00000';
  DECLARE V_CODE INTEGER DEFAULT 0;
  DECLARE V_MSG VARCHAR(2000) DEFAULT '';
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    GET DIAGNOSTICS CONDITION 1 V_STATE = RETURNED_SQLSTATE,
      V_CODE = DB2_RETURNED_SQLCODE, V_MSG = MESSAGE_TEXT;
  SET V_SQL =
       'CREATE OR REPLACE PROCEDURE SQLDFPROBE.P_V30_POS (IN S VARCHAR(20), '
    || 'OUT O_STATE CHAR(5), OUT O_CODE INTEGER, OUT O_N1 INTEGER, OUT O_N2 '
    || 'INTEGER, OUT O_TEXT VARCHAR(200)) LANGUAGE SQL MODIFIES SQL DATA SET '
    || 'OPTION COMMIT = *NONE BEGIN DECLARE V_B VARCHAR(10) DEFAULT ''in''; '
    || 'DECLARE V_C INTEGER DEFAULT 5; DECLARE V_S CHAR(5); DECLARE V_K '
    || 'INTEGER; SET O_STATE = ''00000''; SET O_CODE = 0; BEGIN DECLARE EXIT '
    || 'HANDLER FOR SQLEXCEPTION GET DIAGNOSTICS CONDITION 1 O_STATE = '
    || 'RETURNED_SQLSTATE, O_CODE = DB2_RETURNED_SQLCODE; CALL '
    || 'SQLDFPROBE.P_V30_CALLEE(S, V_B, V_C, V_S, V_K, O_N1, O_N2, O_TEXT); '
    || 'SET O_TEXT = O_TEXT || ''>'' || COALESCE(V_B, ''null'') || ''|'' || '
    || 'COALESCE(TRIM(CHAR(V_C)), ''null''); END; END';
  CALL SQLDFPROBE.RUN_DDL('PROC:V30_POS',
    'DROP PROCEDURE SQLDFPROBE.P_V30_POS', V_SQL);
  IF V_STATE <> '00000' THEN
    INSERT INTO SQLDFPROBE.RESULTS (R_PROBE, R_STEP, R_STATE, R_CODE, R_MSG)
      VALUES ('PROC:V30_POS', 'create', V_STATE, V_CODE,
        'CALL RUN_DDL failed: ' || V_MSG) WITH NC;
  END IF;
END;

