-- V27-MILLIS-BIGINT (V27, decisive): Milliseconds become (CAST(n AS BIGINT) *
--     1000) MICROSECONDS. Is a BIGINT duration of 2147483647000 microseconds
--     accepted and exact (PostgreSQL gives 2024-02-25 06:31:23.770)?
BEGIN
  DECLARE V_STATE CHAR(5) DEFAULT '00000';
  DECLARE V_CODE INTEGER DEFAULT 0;
  DECLARE V_MSG VARCHAR(2000) DEFAULT '';
  DECLARE O_STATE CHAR(5);
  DECLARE O_CODE INTEGER;
  DECLARE O_N1 INTEGER;
  DECLARE O_N2 INTEGER;
  DECLARE O_TEXT VARCHAR(200);
  DECLARE V_ARG1 VARCHAR(4000);
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    GET DIAGNOSTICS CONDITION 1 V_STATE = RETURNED_SQLSTATE,
      V_CODE = DB2_RETURNED_SQLCODE, V_MSG = MESSAGE_TEXT;
  SET V_ARG1 =
       'SELECT CASE WHEN TIMESTAMP(''2024-01-31-10.00.00.123000'') + '
    || '(CAST(2147483647 AS BIGINT) * 1000) MICROSECONDS = '
    || 'TIMESTAMP(''2024-02-25-06.31.23.770000'') THEN 1 ELSE 0 END FROM '
    || 'SYSIBM.SYSDUMMY1';
  CALL SQLDFPROBE.P_V27_INT(V_ARG1, O_STATE, O_CODE, O_N1, O_N2, O_TEXT);
  CALL SQLDFPROBE.LOG_CALL('V27-MILLIS-BIGINT', V_STATE, V_CODE, V_MSG,
    O_STATE, O_CODE, O_N1, O_N2, O_TEXT);
END;

