-- V29-SEQUENCE-CYCLE (V29, decisive): A sequence written out in full, as the
--     converter writes it, hands out 6, 7 and then restarts at MINVALUE 5 (N2
--     = 5), as T-SQL and PostgreSQL do?
BEGIN
  DECLARE V_STATE CHAR(5) DEFAULT '00000';
  DECLARE V_CODE INTEGER DEFAULT 0;
  DECLARE V_MSG VARCHAR(2000) DEFAULT '';
  DECLARE O_STATE CHAR(5);
  DECLARE O_CODE INTEGER;
  DECLARE O_N1 INTEGER;
  DECLARE O_N2 INTEGER;
  DECLARE O_TEXT VARCHAR(200);
  DECLARE V_ARG1 VARCHAR(4000);
  DECLARE V_ARG2 VARCHAR(4000);
  DECLARE V_ARG3 VARCHAR(4000);
  DECLARE V_ARG4 VARCHAR(4000);
  DECLARE V_ARG5 VARCHAR(4000);
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    GET DIAGNOSTICS CONDITION 1 V_STATE = RETURNED_SQLSTATE,
      V_CODE = DB2_RETURNED_SQLCODE, V_MSG = MESSAGE_TEXT;
  SET V_ARG1 =
       'CREATE TABLE SQLDFPROBE.UX (K BIGINT, S VARCHAR(10))';
  SET V_ARG2 =
       'CREATE SEQUENCE SQLDFPROBE.SQ AS INTEGER START WITH 6 INCREMENT BY 1 '
    || 'MINVALUE 5 MAXVALUE 7 CYCLE NO CACHE';
  SET V_ARG3 =
       'INSERT INTO SQLDFPROBE.UX VALUES (NEXT VALUE FOR SQLDFPROBE.SQ, ''a'')';
  SET V_ARG4 =
       'INSERT INTO SQLDFPROBE.UX VALUES (NEXT VALUE FOR SQLDFPROBE.SQ, ''b'')';
  SET V_ARG5 =
       'INSERT INTO SQLDFPROBE.UX VALUES (NEXT VALUE FOR SQLDFPROBE.SQ, ''c'')';
  CALL SQLDFPROBE.P_V29_DDL(V_ARG1, V_ARG2, V_ARG3, V_ARG4, V_ARG5, '',
      O_STATE, O_CODE, O_N1, O_N2, O_TEXT);
  CALL SQLDFPROBE.LOG_CALL('V29-SEQUENCE-CYCLE', V_STATE, V_CODE, V_MSG,
    O_STATE, O_CODE, O_N1, O_N2, O_TEXT);
END;

-- V30-CALL-VARCHAR-LONGER (V30, info): A CALL passes 'abcdefgh' to a
--     VARCHAR(5) parameter. Does Db2 for i fail the call, truncate the value
--     (SQL Server), or pass it whole (PostgreSQL)?
BEGIN
  DECLARE V_STATE CHAR(5) DEFAULT '00000';
  DECLARE V_CODE INTEGER DEFAULT 0;
  DECLARE V_MSG VARCHAR(2000) DEFAULT '';
  DECLARE O_STATE CHAR(5);
  DECLARE O_CODE INTEGER;
  DECLARE O_N1 INTEGER;
  DECLARE O_N2 INTEGER;
  DECLARE O_TEXT VARCHAR(200);
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    GET DIAGNOSTICS CONDITION 1 V_STATE = RETURNED_SQLSTATE,
      V_CODE = DB2_RETURNED_SQLCODE, V_MSG = MESSAGE_TEXT;
  CALL SQLDFPROBE.P_V30_POS('abcdefgh', O_STATE, O_CODE, O_N1, O_N2, O_TEXT);
  CALL SQLDFPROBE.LOG_CALL('V30-CALL-VARCHAR-LONGER', V_STATE, V_CODE, V_MSG,
    O_STATE, O_CODE, O_N1, O_N2, O_TEXT);
END;

