  CALL SQLDFPROBE.LOG_CALL('V30-CALL-OUT-INOUT', V_STATE, V_CODE, V_MSG,
    O_STATE, O_CODE, O_N1, O_N2, O_TEXT);
END;

-- V30-CALL-NAMED-DEFAULT (V30, info): Does a CALL with named arguments (name
--     => value) that leaves out a parameter with a DEFAULT work, and does the
--     parameter get its default (N2 = 7)? Creating the callee also shows
--     whether a parameter with a default may come before ones without.
BEGIN
  DECLARE V_STATE CHAR(5) DEFAULT '00000';
  DECLARE V_CODE INTEGER DEFAULT 0;
  DECLARE V_MSG VARCHAR(2000) DEFAULT '';
  DECLARE O_STATE CHAR(5);
  DECLARE O_CODE INTEGER;
  DECLARE O_N1 INTEGER;
