-- V30-COMMENT-LENGTH (V30, info): How long may a comment be? A 3000-character
--     comment: kept whole (N1 = 3000), cut, or rejected? (PostgreSQL keeps it;
--     an extended property holds up to 7500 bytes.)
BEGIN
  DECLARE V_STATE CHAR(5) DEFAULT '00000';
  DECLARE V_CODE INTEGER DEFAULT 0;
  DECLARE V_MSG VARCHAR(2000) DEFAULT '';
  DECLARE O_STATE CHAR(5);
  DECLARE O_CODE INTEGER;
  DECLARE O_N1 INTEGER;
  DECLARE O_N2 INTEGER;
  DECLARE O_TEXT VARCHAR(200);
  DECLARE V_ARG1 VARCHAR(4000);
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    GET DIAGNOSTICS CONDITION 1 V_STATE = RETURNED_SQLSTATE,
      V_CODE = DB2_RETURNED_SQLCODE, V_MSG = MESSAGE_TEXT;
  SET V_ARG1 =
       'COMMENT ON TABLE SQLDFPROBE.V30V IS '''' || REPEAT(''x'', 3000) || '
    || '''''';
  CALL SQLDFPROBE.P_V30_COMMENT(V_ARG1, O_STATE, O_CODE, O_N1, O_N2, O_TEXT);
  CALL SQLDFPROBE.LOG_CALL('V30-COMMENT-LENGTH', V_STATE, V_CODE, V_MSG,
    O_STATE, O_CODE, O_N1, O_N2, O_TEXT);
END;

-- 4. The results: save or copy every row of this result set.
SELECT 'SQLDFP|1|' || TRIM(CHAR(R_SEQ)) || '|' || R_PROBE
    || '|' || R_STEP
    || '|' || COALESCE(R_STATE, '~')
    || '|' || COALESCE(TRIM(CHAR(R_CODE)), '~')
    || '|' || COALESCE(R_O_STATE, '~')
    || '|' || COALESCE(TRIM(CHAR(R_O_CODE)), '~')
    || '|' || COALESCE(TRIM(CHAR(R_N1)), '~')
    || '|' || COALESCE(TRIM(CHAR(R_N2)), '~')
    || '|' || COALESCE(REPLACE(R_TEXT, '|', '/'), '~')
    || '|' || COALESCE(REPLACE(R_MSG, '|', '/'), '~')
    AS SQLDIFF_PROBE_LINE
  FROM SQLDFPROBE.RESULTS ORDER BY R_SEQ;
